#include <stdio.h>
#include <stdlib.h>

typedef struct { int peso, prioridade; } Encomenda;

int comparar(const void *a, const void *b) {
    const Encomenda *x = a, *y = b;
    if (x->prioridade != y->prioridade) return y->prioridade - x->prioridade;
    return x->peso - y->peso;
}

int main(void) {
    int n;
    scanf("%d", &n);
    Encomenda v[1024];
    for (int i = 0; i < n; i++) scanf("%d %d", &v[i].peso, &v[i].prioridade);
    qsort(v, n, sizeof(Encomenda), comparar);
    for (int i = 0; i < n; i++) printf("%d %d\n", v[i].peso, v[i].prioridade);
    return 0;
}

